// src/components/MovieCard.js

import React from 'react';

function MovieCard({ movie }) {
  // 상세 정보가 객체인지 확인하고, 아니면 빈 배열로 처리
  const detailItems = movie.details && typeof movie.details === 'object' 
    ? Object.entries(movie.details) 
    : [];

  return (
    <div className="movie-card-wrapper">
      {/* 포스터와 오버레이를 포함하는 영역 */}
      <div className="movie-poster-container">
        <div className="rank-badge">{movie.rank}</div>
        <img src={movie.posterPath} alt={movie.title} className="movie-poster-img" />
        
        {/* Hover 시 나타날 오버레이 */}
        <div className="hover-overlay">
          <h3 className="overlay-title-ko">{movie.title}</h3>
          <p className="overlay-title-en">{movie.englishTitle}</p>
          <div className="overlay-details">
            {detailItems.map(([key, value]) => (
              <div key={key} className="detail-item">
                <span className="detail-key">{key}</span>
                <span className="detail-value">{value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
      
      {/* 포스터 하단에 항상 보이는 기본 정보 */}
      <div className="movie-summary">
        <h4 className="summary-title">{movie.title}</h4>
        <p className="summary-info">{movie.summary}</p>
      </div>
    </div>
  );
}

export default MovieCard;
